head.script:
///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.MxDataSet_OnLoadCompleted = function(e) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80400.MxDataSet_OnLoadCompleted" });
    }
};

scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80400.btn_cal_onclick" });
    }
};

scwin.btn_sys_search_onclick = function(e) {
    try {
        if (txb_date.Text !== "") {
            scwin.listSync(); // alert();

        } else {
            alert("기준일자를 지정하십시요");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80400.btn_sys_search_onclick" });
    }
};

scwin.btn_toExcel_onclick = function(e) {
    try {
        $c.data.downloadGridViewExcel(grid01, {fileName: "기업개황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80400.btn_toExcel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.listSync = async function() {
    // var url = "/dartif.do?method=searchDartIF&inputMessageId=job_dartif&outputMessageId=job_dartif&RCV_DDTM="+txb_date.Text; 
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/todayssend.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    toDaySet(txb_date);
};
